package com.example.rokidgeminisecretary;
import android.app.*;import android.widget.*;import org.json.*;
final class MeetingHealthDialog {
 static void show(MainActivity owner){LinearLayout box=new LinearLayout(owner);box.setOrientation(1);box.setPadding(24,12,24,12);TextView status=new TextView(owner);box.addView(status);Button refresh=new Button(owner);refresh.setText("録音進捗を更新");box.addView(refresh);LinearLayout list=new LinearLayout(owner);list.setOrientation(1);box.addView(list);ScrollView scroll=new ScrollView(owner);scroll.addView(box);AlertDialog dialog=new AlertDialog.Builder(owner).setTitle("録音の進捗・保存確認").setView(scroll).setPositiveButton("閉じる",null).create();Runnable update=()->{try{JSONObject s=MeetingControl.status(owner).getJSONObject("state"),p=s.optJSONObject("progress");status.setText((s.optBoolean("connected")?s.optString("status"):"グラス未接続・状態が古い可能性があります")+(p==null?"":"\n取得 "+p.optLong("capturedMs")/1000+"秒 / 書込 "+p.optLong("writtenMs")/1000+"秒 / 確定 "+p.optLong("sealedMs")/1000+"秒"));}catch(Exception e){status.setText("進捗を取得できません");}};refresh.setOnClickListener(v->update.run());dialog.show();update.run();new Thread(()->{try{JSONArray rows=MeetingAudioStore.list(owner);owner.runOnUiThread(()->{if(!dialog.isShowing())return;for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);Button verify=new Button(owner);verify.setText(new java.util.Date(row.optLong("startedAt"))+" / "+row.optLong("durationMs")/1000+"秒：保存区間を検証");verify.setOnClickListener(v->{verify.setEnabled(false);new Thread(()->{String result;try{result=MeetingAudioStore.verify(owner,row.optString("id")).optString("message");}catch(Exception e){result="検証できません。元のグラス録音を保持してください";}final String message=result;owner.runOnUiThread(()->{if(dialog.isShowing()){verify.setText(message);verify.setEnabled(true);}});},"MeetingVerify").start();});list.addView(verify);}});}catch(Exception e){owner.runOnUiThread(()->{if(dialog.isShowing())status.setText("記録一覧を取得できません");});}},"MeetingList").start();}
 private MeetingHealthDialog(){}
}
